const application = items[0].json;
const requiredDocs = [
  { type: 'w2', name: 'W-2 Forms', years: 2, priority: 'high' },
  { type: 'tax_return', name: 'Tax Returns', years: 2, priority: 'high' },
  { type: 'pay_stub', name: 'Pay Stubs', months: 2, priority: 'high' },
  { type: 'bank_statement', name: 'Bank Statements', months: 2, priority: 'high' },
  { type: 'id', name: 'Government ID', priority: 'high' },
  { type: 'employment_letter', name: 'Employment Verification', priority: 'medium' },
  { type: 'credit_authorization', name: 'Credit Authorization', priority: 'high' }
];

const uploadedDocs = application.uploadedDocuments || [];
const missingDocs = requiredDocs.filter(doc => 
  !uploadedDocs.some(uploaded => uploaded.type === doc.type)
);

return [{
  json: {
    ...application,
    requiredDocuments: requiredDocs,
    missingDocuments: missingDocs,
    uploadProgress: ((requiredDocs.length - missingDocs.length) / requiredDocs.length * 100).toFixed(0)
  }
}];

const missingDocs = items[0].json.missingDocuments;
const highPriority = missingDocs.filter(doc => doc.priority === 'high');
const mediumPriority = missingDocs.filter(doc => doc.priority === 'medium');

return [{
  json: {
    ...items[0].json,
    highPriorityDocs: highPriority,
    mediumPriorityDocs: mediumPriority,
    hasHighPriority: highPriority.length > 0
  }
}];
